module dog_chain (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] L,\n    input signed [15:0] x1,\n    input signed [15:0] y1,\n    input signed [15:0] x2,\n    input signed [15:0] y2,\n    output reg done,\n    output reg [7:0] R\n);\n\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COMPUTE_LINE = 3'd1;\n    localparam [2:0] CALC_DISTANCE = 3'd2;\n    localparam [2:0] ITERATE_R = 3'd3;\n    localparam [2:0] CHECK_AREA = 3'd4;\n    localparam [2:0] FINISH = 3'd5;\n\n    reg [2:0] state, next_state;\n    reg [31:0] PI = 32'd205887;  // Q16.16 value of π\n    reg [7:0] r_curr;\n    reg [7:0] cycle_count;\n    reg [31:0] a_reg, b_reg, c_reg;\n    reg [31:0] distance;\n    reg [31:0] S_squared;\n    reg [31:0] area;\n    reg [31:0] denom;\n    reg [15:0] L_reg;\n    wire [31:0] d_val_sq;\n\n    localparam MAX_CYCLES = 8'd200;\n\n    // Always specify bit widths for numeric constants\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            R <= 8'd0;\n            r_curr <= 8'd1;\n            cycle_count <= 8'd0;\n            L_reg <= 16'd0;\n            a_reg <= 32'd0;\n            b_reg <= 32'd0;\n            c_reg <= 32'd0;\n            distance <= 32'd0;\n            S_squared <= 32'd0;\n            denom <= 32'd0;\n            area <= 32'd0;\n        end else begin\n            cycle_count <= cycle_count + 8'd1;\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    cycle_count <= 8'd0;\n                    done <= 1'b0;\n                    if (start) begin\n                        L_reg <= L;\n                        next_state <= COMPUTE_LINE;\n                        cycle_count <= 8'd0;\n                    end\n                end\n\n                COMPUTE_LINE: begin\n                    a_reg <= (y2 - y1);  // a = y2 - y1\n                    b_reg <= (x1 - x2);  // b = x1 - x2\n                    c_reg <= (x2 * y1) - (x1 * y2);  // c = x2*y1 - x1*y2\n                    next_state <= CALC_DISTANCE;\n                end\n\n                CALC_DISTANCE: begin\n                    S_squared <= (a_reg * a_reg) + (b_reg * b_reg);\n                    distance <= (c_reg < 32'd0) ? (-c_reg) : c_reg;  // |c|\n                    next_state <= ITERATE_R;\n                end\n\n                ITERATE_R: begin\n                    if (r_curr > 8'd200 || cycle_count > MAX_CYCLES) begin\n                        R <= 8'd200;\n                        next_state <= FINISH;\n                    end else begin\n                        denom <= S_squared;  // Simplified denominator\n                        next_state <= CHECK_AREA;\n                    end\n                end\n\n                CHECK_AREA: begin\n                    if (distance < denom) begin\n                        area <= (PI * r_curr * r_curr) - (r_curr * r_curr * 32'd51447) \n                                + (distance * 32'd46341);  // Simplified Q16.16 area calc\n                    end else begin\n                        area <= PI * r_curr * r_curr;  // Full circle\n                    end\n\n                    if (area >= {L_reg, 16'd0}) begin  // Compare Q16.16 values\n                        R <= r_curr;\n                        next_state <= FINISH;\n                    end else begin\n                        r_curr <= r_curr + 8'd1;\n                        next_state <= ITERATE_R;\n                    end\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    r_curr <= 8'd1;\n                    if (!start) next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\nendmodule